import os,json,subprocess,re
from pathlib import Path
unit="/etc/systemd/system/pink-vpn.service"
out={"unit":{},"network":{},"services":{},"legacy":{}}
r=subprocess.run(["systemctl","show","pink-vpn","-p","MainPID,ActiveState,SubState,User,ExecMainStatus","--no-pager"],capture_output=True,text=True,timeout=8)
out["unit"]=dict(x.split("=",1) for x in r.stdout.splitlines() if "=" in x)
pid=int(out["unit"].get("MainPID") or 0)
if pid>0:
 try:
  args=(Path("/proc")/str(pid)/"cmdline").read_bytes().split(b"\x00")
  out["unit"]["command_is_canonical"]=any(b"/srv/projects/pink-iptv/vpn/gateway" in x for x in args)
  out["unit"]["command_still_legacy"]=any(b"/etc/pink-vpn" in x for x in args)
  out["unit"]["cwd_in_canonical"]=os.readlink("/proc/"+str(pid)+"/cwd").startswith("/srv/projects/pink-iptv")
 except Exception:pass
for mode in ("-lntp","-lxnp"):
 r=subprocess.run(["ss",mode],capture_output=True,text=True,timeout=8)
 lines=[line for line in r.stdout.splitlines() if "pid="+str(pid)+"," in line]
 out["network"][mode]={"listen_count":len(lines),"local_endpoints":[line.split()[4] if len(line.split())>4 else None for line in lines][:6]}
for n in ("pink-vpn","pink-iptv-backend","nginx","ssh","lowcost-europa","pm2-root","pm2-iptvpn-bot"):
 out["services"][n]=subprocess.run(["systemctl","is-active",n],capture_output=True,text=True,timeout=6).stdout.strip()
for name in ("/etc/pink-vpn","/var/lib/pink-vpn"):
 p=Path(name);out["legacy"][name]={"link":p.is_symlink(),"target":os.readlink(p) if p.is_symlink() else None}
print(json.dumps(out,sort_keys=True))
